6	// Test-only self-describing values. These do not implement a wire format.
7	enum TypedValue { Text(&'static str), Null, Bytes(Vec<u8>) }
8	impl<'de> serde::de::IntoDeserializer<'de, serde::de::value::Error> for TypedValue {
9	    type Deserializer = Self;
10	    fn into_deserializer(self) -> Self { self }
11	}
12	impl<'de> serde::Deserializer<'de> for TypedValue {
13	    type Error = serde::de::value::Error;
14	    fn deserialize_any<V: serde::de::Visitor<'de>>(self, visitor: V) -> Result<V::Value, Self::Error> {
15	        match self {
16	            Self::Text(v) => visitor.visit_str(v),
17	            Self::Null => visitor.visit_unit(),
18	            Self::Bytes(v) => visitor.visit_byte_buf(v),
19	        }
20	    }
21	    serde::forward_to_deserialize_any! {
22	        bool i8 i16 i32 i64 u8 u16 u32 u64 f32 f64 char str string bytes byte_buf
23	        option unit unit_struct newtype_struct seq tuple tuple_struct map struct enum
24	        identifier ignored_any
25	    }
26	}
