31	        ("path", TypedValue::Text("link")), ("kind", TypedValue::Text("symlink")),
32	        ("byteLength", TypedValue::Null), ("contentSha256", TypedValue::Null),
33	        ("executable", TypedValue::Null), ("targetBytes", TypedValue::Bytes(vec![0xff, 0xfe])),
